     * lines with the largest amounts, the earlier line on a tie.
     */
    private List<BigDecimal> inclusiveLineTaxes(BigDecimal taxRate) {
        List<BigDecimal> amounts = inclusiveAmounts();
        int n = lines.size();
        List<BigDecimal> taxes = new ArrayList<>(n);
