            }
            BigDecimal given = zero();
            List<Integer> order = new ArrayList<>();
            for (int i : group.getValue()) {
                BigDecimal tax = taxInside(amounts.get(i), rate);
                // The surcharge and minimum charge keep their own tax, which is not a line's.
                if (i < n) {
                    taxes.set(i, tax);
                    order.add(i);
                }
                given = given.add(tax);
